<?php

// Generated by Claude code
if (PHP_SAPI !== 'cli') {
    http_response_code(403);
    exit('This script can only be run from the command line.');
}

require __DIR__ . '/../vendor/autoload.php';
require __DIR__ . '/../config/db.php';

use Faker\Factory as FakerFactory;

$options = getopt('', ['fresh', 'categories::', 'articles::', 'min-cats::', 'max-cats::', 'help']);

if (isset($options['help'])) {
    echo <<<TXT
    Usage: php bin/seed.php [options]

      --fresh          Wipe existing categories/articles/links before seeding
      --categories=N   Number of categories to seed (default: 8)
      --articles=N     Number of articles to seed (default: 30)
      --min-cats=N     Minimum categories per article (default: 1)
      --max-cats=N     Maximum categories per article (default: 3)
      --help           Show this message

    TXT;
    exit(0);
}


$categoryCount = isset($options['categories']) ? max(1, (int)$options['categories']) : 8;
$articleCount = isset($options['articles']) ? max(1, (int)$options['articles']) : 30;
$minCatsPerArticle = isset($options['min-cats']) ? max(1, (int)$options['min-cats']) : 1;
$maxCatsPerArticle = isset($options['max-cats']) ? max($minCatsPerArticle, (int)$options['max-cats']) : 3;

$categoryPool = [
    'Technology', 'Lifestyle', 'Travel', 'Food', 'Health', 'Business',
    'Science', 'Sports', 'Entertainment', 'Education', 'Finance', 'Culture',
    'Gaming', 'Fashion', 'Nature', 'Music', 'Art', 'Photography',
];
// End Claude code

$pdo = getDbConnection();
$faker = FakerFactory::create();

// Truncate tables for fresh seed
if (isset($options['fresh'])) {
    echo "Remove all existing articles, categories, and links...\n";
    $pdo->exec('SET FOREIGN_KEY_CHECKS = 0');
    $pdo->exec('TRUNCATE TABLE article_categories');
    $pdo->exec('TRUNCATE TABLE articles');
    $pdo->exec('TRUNCATE TABLE categories');
    $pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
}

$pdo->beginTransaction();

try {
    shuffle($categoryPool);
    $names = array_slice($categoryPool, 0, min($categoryCount, count($categoryPool)));

    // Generate additional categories if number of categories to seed is bigger than $categoryPool
    while (count($names) < $categoryCount) {
        $candidate = ucfirst($faker->unique()->word());
        if (!in_array($candidate, $names, true)) {
            $names[] = $candidate;
        }
    }

    $insertCategory = $pdo->prepare('INSERT IGNORE INTO categories (name, description) VALUES (?, ?)');
    foreach ($names as $name) {
        $insertCategory->execute([$name, $faker->sentence(10)]);
    }

    $categoryIds = $pdo->query('SELECT id FROM categories')->fetchAll(PDO::FETCH_COLUMN);

    if (empty($categoryIds)) {
        throw new RuntimeException('No categories available to attach articles to.');
    }

    $insertArticle = $pdo->prepare(
        'INSERT INTO articles (name, description, content, image, views, created_at) VALUES (?, ?, ?, ?, ?, ?)'
    );
    $insertLink = $pdo->prepare('INSERT IGNORE INTO article_categories (article_id, category_id) VALUES (?, ?)');

    for ($i = 0; $i < $articleCount; $i++) {
        // Fake article data prepared by Claude code
        $title = rtrim($faker->sentence(mt_rand(4, 8)), '.');
        $description = $faker->sentence(15);
        $content = implode("\n\n", array_map(
            static fn (string $p): string => "<p>{$p}</p>",
            $faker->paragraphs(mt_rand(4, 8))
        ));
        $image = "https://picsum.photos/seed/article{$i}/640/420";
        $views = $faker->numberBetween(0, 2000);
        $createdAt = $faker->dateTimeBetween('-1 year', 'now')->format('Y-m-d H:i:s');
        // End Claude code

        $insertArticle->execute([$title, $description, $content, $image, $views, $createdAt]);
        $articleId = (int)$pdo->lastInsertId();

        // Connect articles to categories
        $shuffledCategoryIds = $categoryIds;
        shuffle($shuffledCategoryIds);
        $pickCount = mt_rand($minCatsPerArticle, min($maxCatsPerArticle, count($categoryIds)));

        foreach (array_slice($shuffledCategoryIds, 0, $pickCount) as $categoryId) {
            $insertLink->execute([$articleId, $categoryId]);
        }
    }

    $pdo->commit();
} catch (Throwable $e) {
    $pdo->rollBack();
    fwrite(STDERR, 'Seeding failed: ' . $e->getMessage() . PHP_EOL);
    exit(1);
}

// Generated by Claude code
$totalCategories = (int)$pdo->query('SELECT COUNT(*) FROM categories')->fetchColumn();
$totalArticles = (int)$pdo->query('SELECT COUNT(*) FROM articles')->fetchColumn();

echo "Done. categories={$totalCategories} articles={$totalArticles}\n";
// End Claude code
